target.css:
:root {
  --surface: #fffdf8;
  --ink: #253440;
  --muted: #73808a;
  --line: #dbe2df;
  --teal: #167d79;
  --teal-dark: #0f605d;
  --mint: #e3f2ec;
  --coral: #f07c65;
  --cream: #fff4d9;
}

.exchange-card {
  width: 480px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 18px;
  overflow: hidden;
  color: var(--ink);
}

.card-header {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px 18px;
  border-bottom: 1px solid var(--line);
}

.event-mark {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border-radius: 12px;
  background: var(--mint);
  color: var(--teal);
  font-size: 25px;
}

.title-block {
  flex: 1;
}

.kicker,
.subtitle,
.section-label,
.seats {
  margin: 0;
}

.kicker,
.section-label {
  color: var(--teal);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.title-block h1 {
  margin: 2px 0;
  font-size: 20px;
  line-height: 1.15;
}

.subtitle {
  color: var(--muted);
  font-size: 13px;
}

.date-badge {
  display: flex;
  flex-direction: column;
  align-items: center;
  min-width: 42px;
  padding: 5px 4px;
  border-radius: 10px;
  background: var(--cream);
  color: var(--coral);
  line-height: 1;
}

.date-badge strong {
  font-size: 20px;
}

.date-badge span {
  margin-top: 3px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
}

.card-body {
  display: grid;
  grid-template-columns: 1.35fr 0.85fr;
  gap: 14px;
  padding: 14px 18px;
}

.agenda,
.languages {
  display: flex;
  margin: 8px 0 0;
  padding: 0;
  list-style: none;
}

.agenda {
  flex-direction: column;
  gap: 7px;
}

.agenda li {
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: 13px;
}

.agenda li span {
  display: grid;
  place-items: center;
  width: 20px;
  height: 20px;
  border-radius: 6px;
  background: var(--mint);
  color: var(--teal-dark);
  font-size: 12px;
}

.language-panel {
  padding: 10px 12px;
  border-radius: 12px;
  background: var(--mint);
}

.languages {
  gap: 5px;
}

.languages li {
  padding: 4px 6px;
  border-radius: 6px;
  background: var(--surface);
  color: var(--teal-dark);
  font-size: 11px;
  font-weight: 700;
}

.seats {
  margin-top: 8px;
  color: var(--muted);
  font-size: 12px;
}

.seats strong {
  color: var(--coral);
  font-size: 15px;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 11px 18px;
  border-top: 1px solid var(--line);
}

.host {
  color: var(--muted);
  font-size: 12px;
}

.card-footer button {
  border: 0;
  border-radius: 8px;
  padding: 8px 12px;
  background: var(--teal);
  color: var(--surface);
  font-size: 13px;
  font-weight: 700;
}

